"""Generate deduplicated content findings from the shared live crawl; no network."""
from pathlib import Path
import json,collections
R=Path(__file__).resolve().parents[1];c=json.loads((R/'evidence/crawl.json').read_text());a=json.loads((R/'evidence/content-analysis.json').read_text())
by={p.get('final_url',p['url']):p for p in c['pages'] if p.get('status')==200}
base='https://www.letbuyy.com'; en=[x for x in a['articles'] if x['locale']=='in']; quantitative=[x for x in en if 'performance_percent' in x['claim_flags']]
def page(path):return base+path
def record(id,title,severity,state,urls,evidence,impact,fix,owner,effort,deps,validate,indicator,confidence='High',scope='Page-specific'):
 urls=list(dict.fromkeys(urls));return {'issue_id':id,'category':'Content Quality','title':title,'severity':severity,'confidence':confidence,'finding_state':state,'affected_url_count':len(urls),'affected_urls':urls,'representative_urls':urls[:5],'template_or_page':scope,'evidence':evidence,'business_impact':impact,'recommended_fix':fix,'owner_role':owner,'effort':effort,'dependencies':deps,'validation_steps':validate,'success_indicator':indicator,'evidence_files':list(dict.fromkeys(by[u]['evidence_html'] for u in urls if u in by))}
math=[p['url'] for p in c['pages'] if p.get('status')==200 and p['url'].endswith('/how-product-reviews-increase-conversion') and all(n in p.get('main_text','') for n in ['1.7','4.6','270'])]
issues=[]
issues.append(record('CONTENT-01','Conversion-lift headline and calculation overstate the example','High','Confirmed',math,'Shared live HTML in three locale variants retains 1.7%, 4.6% and 270%. (4.6-1.7)/1.7*100=170.5882%; absolute change=2.9 percentage points. The title also promotes 270%. Underlying study/sample was not identified in the article.','Readers receive a materially incorrect quantitative conclusion; it also propagates to titles and article/card text. No ranking loss is established.','Correct the relative-increase calculation and all synchronized titles, summaries, schema/cards and translations. Alternatively remove the numerical promise until a faithfully scoped original source is available. Do not present arithmetic correction as validation of the original study.','Editor + analytics/research reviewer','2-6 hours assuming translation support and underlying source access','Claim/source ledger; translation review','Recompute from cited original values; compare title, H1, body, summaries and schema in all three languages; verify the source population/date/outcome.','Zero arithmetic contradictions across the three article variants and their metadata.','High','Shared article record across three locales'))
issues.append(record('CONTENT-02','Quantified article claims lack traceable in-body references','High','Confirmed',[x['url'] for x in quantitative],f"Within all 35 English articles, body-container extraction finds no external reference anchors. {len(quantitative)} English articles contain percentage-pattern claims. Examples include exact payment shares/performance gains and growth/retention statistics. UPI guide also makes categorical zero-failure, fee and settlement assertions. Absence of citations does not prove every claim false; current fee and other factual applicability remain unverified.",'Material numerical and financial assertions are difficult for readers or reviewers to verify; generic nationwide claims can be misapplied to a merchant.','Build a source ledger for each material figure/categorical assertion: exact statement, source URL, date, sample/population, metric definition, scope and review owner. Cite primary sources beside claims, qualify estimates and remove unsupported guarantees. Distinguish national payment volume from ecommerce share, transfer confirmation from merchant settlement, and RTO from customer returns. Add safe link/citation capability to the existing content contract/renderer when needed.','Subject editor + product/payments specialist; web engineer for citation support','3-7 working days for the first 19 English articles plus scoped translations, assuming source access; not a delivery promise','Current primary data/provider terms; safe citation rendering; qualified review for financial/tax statements','Verify every retained material numerical claim against the exact primary source and effective date; check citations appear as crawlable links in initial HTML; translations preserve scope. Review facts, not merely link counts.','All retained material claims in the priority article set have a supporting source/methodology or a visible illustrative/estimate label.','High for missing references; truth of most figures unverified','19 English article pages; related translations require synchronized review'))
provenance=[page('/in/resources/ecommerce/how-to-start-an-online-store-india'),page('/in/resources/authors/priya-commerce'),page('/in/resources/authors/neha-payments'),page('/in/resources/authors/ravi-operations')]
provenance=[u for u in provenance if u in by]
issues.append(record('CONTENT-03','Merchant outcomes and expert biographies need provenance verification','High','Needs verification',provenance,'The live launch guide describes a Jaipur merchant migration in April2026 with conversion changing34% to61% in60days and COD orders doubling, labelled Commerce Example rather than explicitly hypothetical. Inspected author pages claim prior employer experience, a GST-consultant role and work with200brands. Page-level evidence does not substantiate those identities/outcomes. This audit has not established that they are false.','Specific-looking customer results and professional credentials can affect merchant trust and financial decisions; markup cannot compensate for unsupported provenance.','Obtain authorized records for actual results and biographies. Retain only accurate claims; otherwise remove unsupported credentials or use an honest team byline. Explicitly label hypothetical teaching scenarios and inputs. Keep actual customer data private and publish only authorized evidence.','Editorial owner + business/product owner; real named reviewers where applicable','1-3 days to resolve priority claims if records/owners are available; otherwise remove/qualify pending verification','Human-owned factual records and consent; truthful author/entity policy','For each result, verify data window, denominator, calculation, confounders and publishing permission. For each biography, verify actual identity/role and consent. Check article, author page, schema and translations agree.','Zero unverified customer outcomes or credentials presented as established facts in the reviewed set.','High for observed wording; underlying provenance unverified','One English article and three English author profiles'))
availability=[page('/in/resources/platform/introduction-to-apps'),page('/in/resources/ai-commerce/commerce-copilot-guide')]
availability=[u for u in availability if u in by]
issues.append(record('CONTENT-04','Feature-action guides leave general availability unclear','Medium','Needs verification',availability,'Live guides present app installation and an always-on AI copilot as actionable current experiences. Pricing labels Scale/Commerce OS coming soon; legal text distinguishes closed publishing surfaces. Installing curated apps can coexist with closed public publishing, so this is an availability ambiguity, not proof the product is absent. Actual entitlement and provider readiness were not exercised.','Visitors may follow a task guide to an action they cannot access or purchase, weakening task completion and offer clarity.','Reconcile each documented action with the product/plan/realm/provider availability authority. Add clear available-now, restricted-access, setup-required or planned labels and prerequisites. Separate concepts from procedures. Correct promises without activating frozen runtimes or inventing release dates.','Product documentation owner + product/billing owner','0.5-2 days for reviewed status matrix and priority guides, assuming availability facts exist','Approved feature/entitlement facts; current pricing/legal wording','Trace each guide step to an actual authorized product path and eligible plan; verify accessible alternatives for ineligible users; compare guides, FAQ, prices and legal status. No real transaction required.','Every actionable priority guide states accurate access prerequisites and current availability.','High for wording; actual general availability unverified','Two English task guides; availability review applies to related guides'))
issues.append(record('CONTENT-05','Article bodies omit contextual links to prerequisite and next-step guides','Medium','Opportunity',[x['url'] for x in en],'All35 English article-body containers have zero contextual internal anchors in the shared live HTML. Heading self-links exist; breadcrumbs, tags and related cards provide article discovery outside the body. This is not evidence of orphan pages or a required link-count violation.','Readers must leave the task context to find prerequisite detail; source references and next-step guidance are less direct.','Add relevant contextual links at actual decision points using the existing localized link/content contract. Prioritize launch→GST/payments/shipping, UPI/COD→setup/refunds, and supported procedure→troubleshooting. Use the proposed44-link matrix as editorial guidance, not a mechanical quota.','Content editor + web engineer','1-3 days for initial launch/payment clusters, assuming safe link rendering','Corrected target content; canonical/locale URL policy; safe content contract','Verify links in initial HTML, correct locale/final200 destination, meaningful anchor and reader relevance. Preserve related cards and discovery; check no article becomes orphaned.','Every priority task guide links directly to the prerequisites and next steps necessary for its task; zero broken proposed links after implementation.','High for body-link absence; benefit is a hypothesis','Shared article-body pattern across35 English pages'))
(R/'findings/content-issues.json').write_text(json.dumps(issues,ensure_ascii=False,indent=2))
lines=['# Content quality and strategy findings','', '29 October2026 · Shared fresh live crawl; source is used only for implementation navigation.','', '**Assessment:** The site has an existing useful topical structure. The highest priority is factual reliability and honest product/author/result presentation, followed by source-linked task completion. There is no basis to infer AI authorship, a penalty, or ranking impact from phrasing, page length or template count. No numeric E-E-A-T score is assigned.','',f"**Evidence scope:** {len(en)} English article bodies inspected; translated arithmetic variants separately checked. Cite evidence/content-analysis.json and each raw HTML capture below. Body-reference counts exclude unrelated navigation/social links. Saved article content remains the authoritative capture; the regex percentage screen is a candidate selector, not a fact checker.",'']
for i in issues:
 lines += ['## '+i['issue_id']+' — '+i['title'],'',f"**Severity/state/confidence:** {i['severity']} · {i['finding_state']} · {i['confidence']}",f"**Affected inspected URLs:** {i['affected_url_count']} · {i['template_or_page']}",'', '**Evidence:** '+i['evidence'],'','**Representative URLs:** '+', '.join('['+u.split('/in/')[-1]+']('+u+')' for u in i['representative_urls']),'','**Saved evidence:** '+', '.join('['+Path(f).name+'](../'+f+')' for f in i['evidence_files'][:5]),'','**Why it matters:** '+i['business_impact'],'','**Correction:** '+i['recommended_fix'],'','**Owner/effort:** '+i['owner_role']+' · '+i['effort'],'','**Dependencies:** '+i['dependencies'],'','**Validation:** '+i['validation_steps'],'','**Success indicator:** '+i['success_indicator'],'']
lines += ['## Tax and current financial claims','', 'The parent audit owns the separate tax finding to prevent duplication. Exact guide statements needing review include registration thresholds, blanket marketplace registration, TCS1%, category rates and unconditional filing schedules. Official2023exemption/2024TCS/2025rate material is handled in the main audit; the content team must update adjacent setup/invoice guides and translations together. A GSTR2A mention is not automatically wrong: the official portal documents TCS details in PartC. Current provider fee claims must be checked against current policy; this analysis does not invent a replacement fee schedule.','', '## Current strengths and limits','', 'Articles have useful headings, dates, bylines, category/tag discovery, related reading, concept illustrations and several task checklists. The seven categories map to actual merchant and developer questions. Keep those strengths. No measured query-to-page cannibalization, keyword demand, reader testing, author credential confirmation or customer-record verification was available in this subtask. The full audit supplies technical/performance and access coverage.','', 'See [CONTENT-AND-CLUSTER-PLAN.md](../CONTENT-AND-CLUSTER-PLAN.md) for four detailed upgrade briefs, page ownership, provisional36-phrase intent mapping and proposed44-link matrix.','', '## Primary methodology references','', '[Google helpful-content guidance](https://developers.google.com/search/docs/fundamentals/creating-helpful-content) emphasizes reliable sourcing, demonstrable experience and original usefulness. It explicitly rejects a preferred Google word count. These findings use evidence of factual/source/task gaps, not a length-based quality score. [Google spam policies](https://developers.google.com/search/docs/essentials/spam-policies) explain doorway/scaled-content concerns; no policy violation or penalty is asserted here.']
(R/'findings/content-strategy.md').write_text('\n'.join(lines)+'\n')
coverage=[]
for route,status,why,out,missing,nextstep in [
 ('content','executed','Existing public article library and material commercial/compliance claims','findings/content-strategy.md; findings/content-issues.json; evidence/content-analysis.json','Real author/customer/claim provenance remains unverified','Editorial owners verify provenance and sources; implement only after approval of factual changes'),
 ('content-brief','executed','Existing launch/pricing/payment/tax pages have concrete correctness/task gaps','CONTENT-AND-CLUSTER-PLAN.md: four detailed improve-mode briefs','Controlled top5 rankings, competitor word averages and numeric gap scores not measured','Use consistent India query dataset and first-party query/page data when available; no new URL required now'),
 ('cluster','partially executed','Resource library supports topic architecture and contextual links','cluster-plan.json; cluster-map.html; internal-link-matrix.csv; CONTENT-AND-CLUSTER-PLAN.md','Consistent top10 organic URL datasets and keyword volumes unavailable','Collect EnglishIndia device/location/time-controlled SERPs for36phrases; compute overlap before consolidation'),
 ('programmatic','partially executed','Tag/category/author/locale templates create scaled page patterns','CONTENT-AND-CLUSTER-PLAN.md: archive policy; main crawl technical analysis','Actual indexing/query data and complete information-gain review unavailable','Review useful landing intents and discovery before changing indexation; do not apply word-count deletion'),
 ('plan','executed','Business-specific prioritization can proceed from observed correctness/IA gaps','CONTENT-AND-CLUSTER-PLAN.md; main PRIORITIZED-ACTION-PLAN.md','Measured performance/traffic targets and owner capacity unavailable','Use outcome-based correctness batches; set quantitative business targets after baseline analytics access'),
 ('flow','executed','Find/Optimize/Win synthesis fits the observed product and trust/offer gaps','CONTENT-AND-CLUSTER-PLAN.md: FLOW synthesis and exact attribution','Off-site evidence, first-party conversion data and local-business applicability not established','Apply only supported stages; preserve attribution; no outreach or local-profile changes')]:
 coverage.append({'route':route,'applicable':True,'why':why,'status':status,'evidence_or_output':out,'missing_prerequisite':missing,'next_step':nextstep})
(R/'findings/content-coverage.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2))
print('Wrote5contentissues; counts',[(i['issue_id'],i['affected_url_count'],i['finding_state']) for i in issues]);print('crawl_complete',c['complete'])
